Here is the commit message:
mmc: meson-mx-sdio: add IRQ check

The driver neglects to check the result of platform_get_irq()'s call and
blithely passes the negative error codes to devm_request_threaded_irq()
(which takes *unsigned* IRQ #), causing it to fail with -EINVAL, overriding
an original error code. Stop calling devm_request_threaded_irq() with the
invalid IRQ #s.

Fixes: ed80a13bb4c4 ("mmc: meson-mx-sdio: Add a driver for the Amlogic Meson8 and Meson8b SoC")
Signed-off-by: Sergey Shtylyov <s.shtylyov@omp.ru>
Reviewed-by: Martin Blumenstingl <martin.blumenstingl@googlemail.com>
Link: https://lore.kernel.org/r/20211217202717.10041-3-s.shtylyov@omp.ru
Signed-off-by: Ulf Hansson <ulf.hansson@linaro.org>

Here is the root cause:
The bug arises from the driver not checking the return value of `platform_get_irq()`, which can return a negative error code if it fails to retrieve a valid IRQ number. This negative value is then incorrectly passed to `devm_request_threaded_irq()`, which expects an unsigned IRQ number, leading to an `-EINVAL` error and masking the original error code.

Here is the patch:

 static int meson_mx_mmc_probe(struct platform_device *pdev)
 {
 	struct platform_device *slot_pdev;
 	struct mmc_host *mmc;
 	struct meson_mx_mmc_host *host;
 	int ret, irq;
 	u32 conf;

 	slot_pdev = meson_mx_mmc_slot_pdev(&pdev->dev);
 	if (!slot_pdev)
 		return -ENODEV;
 	else if (IS_ERR(slot_pdev))
 		return PTR_ERR(slot_pdev);

 	mmc = mmc_alloc_host(sizeof(*host), &slot_pdev->dev);
 	if (!mmc) {
 		ret = -ENOMEM;
 		goto error_unregister_slot_pdev;
 	}

 	host = mmc_priv(mmc);
 	host->mmc = mmc;
 	host->controller_dev = &pdev->dev;

 	spin_lock_init(&host->irq_lock);
 	timer_setup(&host->cmd_timeout, meson_mx_mmc_timeout, 0);

 	platform_set_drvdata(pdev, host);

 	host->base = devm_platform_ioremap_resource(pdev, 0);
 	if (IS_ERR(host->base)) {
 		ret = PTR_ERR(host->base);
 		goto error_free_mmc;
 	}

 	irq = platform_get_irq(pdev, 0);
+	if (irq < 0) {
+		ret = irq;
+		goto error_free_mmc;
+	}
+
 	ret = devm_request_threaded_irq(host->controller_dev, irq,
 					meson_mx_mmc_irq,
 					meson_mx_mmc_irq_thread, IRQF_ONESHOT,
 					NULL, host);
 	if (ret)
 		goto error_free_mmc;

 	host->core_clk = devm_clk_get(host->controller_dev, "core");
 	if (IS_ERR(host->core_clk)) {
 		ret = PTR_ERR(host->core_clk);
 		goto error_free_mmc;
 	}

 	host->parent_clk = devm_clk_get(host->controller_dev, "clkin");
 	if (IS_ERR(host->parent_clk)) {
 		ret = PTR_ERR(host->parent_clk);
 		goto error_free_mmc;
 	}

 	ret = meson_mx_mmc_register_clks(host);
 	if (ret)
 		goto error_free_mmc;

 	ret = clk_prepare_enable(host->core_clk);
 	if (ret) {
 		dev_err(host->controller_dev, "Failed to enable core clock\n");
 		goto error_free_mmc;
 	}

 	ret = clk_prepare_enable(host->cfg_div_clk);
 	if (ret) {
 		dev_err(host->controller_dev, "Failed to enable MMC clock\n");
 		goto error_disable_core_clk;
 	}

 	conf = 0;
 	conf |= FIELD_PREP(MESON_MX_SDIO_CONF_CMD_ARGUMENT_BITS_MASK, 39);
 	conf |= FIELD_PREP(MESON_MX_SDIO_CONF_M_ENDIAN_MASK, 0x3);
 	conf |= FIELD_PREP(MESON_MX_SDIO_CONF_WRITE_NWR_MASK, 0x2);
 	conf |= FIELD_PREP(MESON_MX_SDIO_CONF_WRITE_CRC_OK_STATUS_MASK, 0x2);
 	writel(conf, host->base + MESON_MX_SDIO_CONF);

 	meson_mx_mmc_soft_reset(host);

 	ret = meson_mx_mmc_add_host(host);
 	if (ret)
 		goto error_disable_clks;

 	return 0;

 error_disable_clks:
 	clk_disable_unprepare(host->cfg_div_clk);
 error_disable_core_clk:
 	clk_disable_unprepare(host->core_clk);
 error_free_mmc:
 	mmc_free_host(mmc);
 error_unregister_slot_pdev:
 	of_platform_device_destroy(&slot_pdev->dev, NULL);
 	return ret;
 }



